INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M29-CI001', 'HDSAT-RW-M29-CI001', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'Plate tectonics (from Latin tectonicus, from Ancient Greek τεκτονικός (tektonikós) ''pertaining to building'') is the scientific theory that Earth''s lithosphere comprises a number of large tectonic plates, which have been slowly moving since 3–4 billion years ago. The model builds on the concept of continental drift, an idea developed during the first decades of the 20th century. Plate tectonics came to be accepted by geoscientists after seafloor spreading was validated in the mid- to late 1960s. The processes that result in plates and shape Earth''s crust are called tectonics. Earth''s lithosphere, the rigid outer shell of the planet including the crust and upper mantle, is fractured into seven or eight major plates (depending on how they are defined) and many minor plates or "platelets". Where the plates meet, their relative motion determines the type of plate boundary (or fault): convergent, divergent, or transform. The relative movement of the plates typically ranges from zero to 10 cm annually. Faults tend to be geologically active, with earthquakes, volcanic activity, mountain-building, and oceanic trench formation. Tectonic plates are composed of the oceanic lithosphere and the thicker continental lithosphere, each topped by its own kind of crust. Along convergent plate boundaries, the process of subduction carries the edge of one plate down under the other plate and into the mantle. This process reduces the total surface area (crust) of Earth.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Plate tectonics was accepted before continental drift was proposed."}, {"id": "B", "text": "Plate tectonics claims Earth''s crust is a single unmoving shell."}, {"id": "C", "text": "Plate boundaries produce no geological activity."}, {"id": "D", "text": "Plate tectonics explains Earth''s moving lithospheric plates and the earthquakes, volcanoes, and mountains at their boundaries."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Plate tectonics", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Plate_tectonics', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M29-CI001', 'D', ARRAY['D']::TEXT[], 'The passage defines the theory, traces its acceptance, and describes plate boundaries and their effects.', '{"B": "The text describes the lithosphere as fractured into moving plates.", "A": "The text says the model builds on continental drift and was accepted after seafloor spreading was validated.", "C": "The text says faults are geologically active with earthquakes and volcanism."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M29-INF001', 'HDSAT-RW-M29-INF001', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'Plate tectonics (from Latin tectonicus, from Ancient Greek τεκτονικός (tektonikós) ''pertaining to building'') is the scientific theory that Earth''s lithosphere comprises a number of large tectonic plates, which have been slowly moving since 3–4 billion years ago. The model builds on the concept of continental drift, an idea developed during the first decades of the 20th century. Plate tectonics came to be accepted by geoscientists after seafloor spreading was validated in the mid- to late 1960s. The processes that result in plates and shape Earth''s crust are called tectonics. Earth''s lithosphere, the rigid outer shell of the planet including the crust and upper mantle, is fractured into seven or eight major plates (depending on how they are defined) and many minor plates or "platelets". Where the plates meet, their relative motion determines the type of plate boundary (or fault): convergent, divergent, or transform. The relative movement of the plates typically ranges from zero to 10 cm annually. Faults tend to be geologically active, with earthquakes, volcanic activity, mountain-building, and oceanic trench formation. Tectonic plates are composed of the oceanic lithosphere and the thicker continental lithosphere, each topped by its own kind of crust. Along convergent plate boundaries, the process of subduction carries the edge of one plate down under the other plate and into the mantle. This process reduces the total surface area (crust) of Earth.
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M29-INF001', 'D', ARRAY['D']::TEXT[], 'The passage explicitly says subduction reduces total crustal surface area.', '{"C": "The text states that subduction reduces the total surface area of Earth''s crust.", "A": "Subduction consumes crust rather than balancing it.", "B": "Subduction is part of continued plate motion."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M29-TS001', 'HDSAT-RW-M29-TS001', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'Plate tectonics (from Latin tectonicus, from Ancient Greek τεκτονικός (tektonikós) ''pertaining to building'') is the scientific theory that Earth''s lithosphere comprises a number of large tectonic plates, which have been slowly moving since 3–4 billion years ago. The model builds on the concept of continental drift, an idea developed during the first decades of the 20th century. Plate tectonics came to be accepted by geoscientists after seafloor spreading was validated in the mid- to late 1960s. The processes that result in plates and shape Earth''s crust are called tectonics. Earth''s lithosphere, the rigid outer shell of the planet including the crust and upper mantle, is fractured into seven or eight major plates (depending on how they are defined) and many minor plates or "platelets". Where the plates meet, their relative motion determines the type of plate boundary (or fault): convergent, divergent, or transform. The relative movement of the plates typically ranges from zero to 10 cm annually. Faults tend to be geologically active, with earthquakes, volcanic activity, mountain-building, and oceanic trench formation. Tectonic plates are composed of the oceanic lithosphere and the thicker continental lithosphere, each topped by its own kind of crust. Along convergent plate boundaries, the process of subduction carries the edge of one plate down under the other plate and into the mantle. This process reduces the total surface area (crust) of Earth.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It narrates a single earthquake caused by a fault."}, {"id": "B", "text": "It compares Earth''s plates with those of Mars."}, {"id": "C", "text": "It argues that continental drift was correct in every detail."}, {"id": "D", "text": "It defines plate tectonics, traces its development, and describes plate types, boundaries, and effects."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Plate tectonics", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Plate_tectonics', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M29-TS001', 'D', ARRAY['D']::TEXT[], 'The passage moves from definition and history to mechanics and consequences.', '{"A": "No individual earthquake is narrated.", "B": "Mars is not mentioned.", "C": "The text says the model builds on continental drift, not that every detail was right."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M29-CE001', 'HDSAT-RW-M29-CE001', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Textual)', 'Medium', 'multiple_choice', 'Plate tectonics (from Latin tectonicus, from Ancient Greek τεκτονικός (tektonikós) ''pertaining to building'') is the scientific theory that Earth''s lithosphere comprises a number of large tectonic plates, which have been slowly moving since 3–4 billion years ago. The model builds on the concept of continental drift, an idea developed during the first decades of the 20th century. Plate tectonics came to be accepted by geoscientists after seafloor spreading was validated in the mid- to late 1960s. The processes that result in plates and shape Earth''s crust are called tectonics. Earth''s lithosphere, the rigid outer shell of the planet including the crust and upper mantle, is fractured into seven or eight major plates (depending on how they are defined) and many minor plates or "platelets". Where the plates meet, their relative motion determines the type of plate boundary (or fault): convergent, divergent, or transform. The relative movement of the plates typically ranges from zero to 10 cm annually. Faults tend to be geologically active, with earthquakes, volcanic activity, mountain-building, and oceanic trench formation. Tectonic plates are composed of the oceanic lithosphere and the thicker continental lithosphere, each topped by its own kind of crust. Along convergent plate boundaries, the process of subduction carries the edge of one plate down under the other plate and into the mantle. This process reduces the total surface area (crust) of Earth.', 'Which quotation from the text most directly supports the claim that the plates move slowly?', '[{"id": "A", "text": "The relative movement of the plates typically ranges from zero to 10 cm annually."}, {"id": "B", "text": "Earth''s lithosphere is fractured into seven or eight major plates and many minor plates."}, {"id": "C", "text": "Along convergent plate boundaries, the process of subduction carries the edge of one plate down under the other plate."}, {"id": "D", "text": "Where the plates meet, their relative motion determines the type of plate boundary."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Plate tectonics", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Plate_tectonics', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M29-CE001', 'A', ARRAY['A']::TEXT[], 'The correct quotation gives the annual movement rate.', '{"B": "This sentence describes the number of plates.", "D": "This sentence describes boundary types.", "C": "This sentence describes subduction."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M29-CI002', 'HDSAT-RW-M29-CI002', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'A volcano is a vent or fissure in the crust of a planetary-mass object that allows hot lava, volcanic ash, and gases to escape from a magma chamber below the surface. On Earth, volcanoes are most often found where tectonic plates are diverging or converging, and because most of Earth''s plate boundaries are underwater, most volcanoes are found underwater. For example, a mid-ocean ridge, such as the Mid-Atlantic Ridge, has volcanoes caused by divergent tectonic plates whereas the Pacific Ring of Fire has volcanoes caused by convergent tectonic plates. Volcanoes resulting from divergent tectonic activity are usually nonexplosive whereas those resulting from convergent tectonic activity cause violent eruptions. Volcanoes can also form where there is stretching and thinning of the crust''s plates, such as in the East African Rift, the Wells Gray-Clearwater volcanic field, and the Rio Grande rift in North America. Volcanism away from plate boundaries most likely arises from upwelling diapirs from the core–mantle boundary called mantle plumes, 3,000 kilometres (1,900 mi) deep within Earth. This results in hotspot volcanism or intraplate volcanism, in which the plume may cause thinning of the crust and result in a volcanic island chain due to the continuous movement of the tectonic plate, of which the Hawaiian hotspot is an example. Volcanoes are usually not created at transform tectonic boundaries where two tectonic plates slide past one another.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Volcanoes occur only on land and only at transform boundaries."}, {"id": "B", "text": "Volcanoes are unrelated to tectonic plate movement."}, {"id": "C", "text": "All volcanic eruptions are violent and explosive."}, {"id": "D", "text": "Volcanoes are vents that release lava, ash, and gas, mostly at plate boundaries and mostly underwater, with eruption style tied to boundary type."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Volcano", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Volcano', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M29-CI002', 'D', ARRAY['D']::TEXT[], 'The passage defines volcanoes, describes where they occur, and contrasts eruption styles.', '{"A": "The text says most volcanoes are underwater and usually not created at transform boundaries.", "C": "The text says divergent-boundary volcanoes are usually nonexplosive.", "B": "The text explains volcanoes through diverging and converging plates."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M29-INF002', 'HDSAT-RW-M29-INF002', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'A volcano is a vent or fissure in the crust of a planetary-mass object that allows hot lava, volcanic ash, and gases to escape from a magma chamber below the surface. On Earth, volcanoes are most often found where tectonic plates are diverging or converging, and because most of Earth''s plate boundaries are underwater, most volcanoes are found underwater. For example, a mid-ocean ridge, such as the Mid-Atlantic Ridge, has volcanoes caused by divergent tectonic plates whereas the Pacific Ring of Fire has volcanoes caused by convergent tectonic plates. Volcanoes resulting from divergent tectonic activity are usually nonexplosive whereas those resulting from convergent tectonic activity cause violent eruptions. Volcanoes can also form where there is stretching and thinning of the crust''s plates, such as in the East African Rift, the Wells Gray-Clearwater volcanic field, and the Rio Grande rift in North America. Volcanism away from plate boundaries most likely arises from upwelling diapirs from the core–mantle boundary called mantle plumes, 3,000 kilometres (1,900 mi) deep within Earth. This results in hotspot volcanism or intraplate volcanism, in which the plume may cause thinning of the crust and result in a volcanic island chain due to the continuous movement of the tectonic plate, of which the Hawaiian hotspot is an example. Volcanoes are usually not created at transform tectonic boundaries where two tectonic plates slide past one another.
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M29-INF002', 'A', ARRAY['A']::TEXT[], 'The passage directly connects underwater boundaries to underwater volcanoes.', '{"D": "The text states that because most boundaries are underwater, most volcanoes are found underwater.", "B": "Continental settings are the minority.", "C": "The text says volcanoes are usually not created at transform boundaries."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M29-TS002', 'HDSAT-RW-M29-TS002', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'A volcano is a vent or fissure in the crust of a planetary-mass object that allows hot lava, volcanic ash, and gases to escape from a magma chamber below the surface. On Earth, volcanoes are most often found where tectonic plates are diverging or converging, and because most of Earth''s plate boundaries are underwater, most volcanoes are found underwater. For example, a mid-ocean ridge, such as the Mid-Atlantic Ridge, has volcanoes caused by divergent tectonic plates whereas the Pacific Ring of Fire has volcanoes caused by convergent tectonic plates. Volcanoes resulting from divergent tectonic activity are usually nonexplosive whereas those resulting from convergent tectonic activity cause violent eruptions. Volcanoes can also form where there is stretching and thinning of the crust''s plates, such as in the East African Rift, the Wells Gray-Clearwater volcanic field, and the Rio Grande rift in North America. Volcanism away from plate boundaries most likely arises from upwelling diapirs from the core–mantle boundary called mantle plumes, 3,000 kilometres (1,900 mi) deep within Earth. This results in hotspot volcanism or intraplate volcanism, in which the plume may cause thinning of the crust and result in a volcanic island chain due to the continuous movement of the tectonic plate, of which the Hawaiian hotspot is an example. Volcanoes are usually not created at transform tectonic boundaries where two tectonic plates slide past one another.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It narrates a single historic eruption."}, {"id": "B", "text": "It argues that volcanoes cannot be studied."}, {"id": "C", "text": "It defines volcanoes, explains their distribution at plate boundaries, and describes hotspot and intraplate volcanism."}, {"id": "D", "text": "It compares Earth''s volcanoes with those on the Moon."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Volcano", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Volcano', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M29-TS002', 'C', ARRAY['C']::TEXT[], 'The passage moves from definition to distribution, eruption style, and hotspots.', '{"A": "No single eruption is narrated.", "D": "The Moon is not discussed.", "B": "The text explains volcanic mechanisms in detail."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M29-CE002', 'HDSAT-RW-M29-CE002', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Textual)', 'Medium', 'multiple_choice', 'A volcano is a vent or fissure in the crust of a planetary-mass object that allows hot lava, volcanic ash, and gases to escape from a magma chamber below the surface. On Earth, volcanoes are most often found where tectonic plates are diverging or converging, and because most of Earth''s plate boundaries are underwater, most volcanoes are found underwater. For example, a mid-ocean ridge, such as the Mid-Atlantic Ridge, has volcanoes caused by divergent tectonic plates whereas the Pacific Ring of Fire has volcanoes caused by convergent tectonic plates. Volcanoes resulting from divergent tectonic activity are usually nonexplosive whereas those resulting from convergent tectonic activity cause violent eruptions. Volcanoes can also form where there is stretching and thinning of the crust''s plates, such as in the East African Rift, the Wells Gray-Clearwater volcanic field, and the Rio Grande rift in North America. Volcanism away from plate boundaries most likely arises from upwelling diapirs from the core–mantle boundary called mantle plumes, 3,000 kilometres (1,900 mi) deep within Earth. This results in hotspot volcanism or intraplate volcanism, in which the plume may cause thinning of the crust and result in a volcanic island chain due to the continuous movement of the tectonic plate, of which the Hawaiian hotspot is an example. Volcanoes are usually not created at transform tectonic boundaries where two tectonic plates slide past one another.', 'Which quotation from the text most directly supports the claim that convergent boundaries produce violent eruptions?', '[{"id": "A", "text": "Volcanoes resulting from divergent tectonic activity are usually nonexplosive whereas those resulting from convergent tectonic activity cause violent eruptions."}, {"id": "B", "text": "Most volcanoes are found underwater because most of Earth''s plate boundaries are underwater."}, {"id": "C", "text": "A volcano is a vent or fissure in the crust of a planetary-mass object that allows hot lava, volcanic ash, and gases to escape."}, {"id": "D", "text": "Volcanoes are usually not created at transform tectonic boundaries."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Volcano", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Volcano', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M29-CE002', 'A', ARRAY['A']::TEXT[], 'The correct quotation contrasts nonexplosive divergent volcanoes with violent convergent ones.', '{"C": "This sentence defines a volcano.", "B": "This sentence explains underwater volcanism.", "D": "This sentence describes transform boundaries."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M29-CI003', 'HDSAT-RW-M29-CI003', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'A glacier (US: ; UK: or ) is a persistent body of natural ice, a form of rock, that is constantly moving under its own weight. A glacier forms where the accumulation of snow exceeds its ablation over many years, often centuries. It slowly flows and deforms under stresses induced by gravity, undergoing both ductile and brittle deformation, and acquiring distinguishing surface features, such as crevasses and seracs. As a glacier moves, it abrades underlying rock and debris to create glacial landforms, such as cirques, moraines, and fjords. Although a glacier may flow into a body of water, and can include ice shelves and ice tongues, it originates only on land and is distinct from the much thinner sea ice and lake ice that form on the surface of freezing bodies of water. On Earth, 99% of glacial ice is contained within vast ice sheets (also known as "continental glaciers") in the polar regions, but glaciers may be found in mountain ranges on every continent other than the Australian mainland, including Oceania''s high-latitude oceanic island countries such as New Zealand. Between latitudes 35°N and 35°S, glaciers occur only in the Himalayas, Andes, and a few high mountains in East Africa, Mexico, New Guinea and on Zard-Kuh in Iran. With more than 7,000 known glaciers, Pakistan has more glacial ice than any other country outside the polar regions. Glaciers cover about 10% of Earth''s land surface.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Glaciers are the same as sea ice."}, {"id": "B", "text": "Glaciers form where melting exceeds snowfall."}, {"id": "C", "text": "A glacier is a stationary block of ice that never moves."}, {"id": "D", "text": "A glacier is a persistent, moving body of land ice formed where snowfall exceeds melting, and it shapes the landscape as it flows."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Glacier", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Glacier', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M29-CI003', 'D', ARRAY['D']::TEXT[], 'The passage defines glaciers, explains formation and movement, and describes their distribution and landforms.', '{"C": "The text says a glacier is constantly moving under its own weight.", "B": "The text says it forms where accumulation of snow exceeds ablation.", "A": "The text distinguishes glaciers from sea ice and lake ice."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M29-INF003', 'HDSAT-RW-M29-INF003', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'A glacier (US: ; UK: or ) is a persistent body of natural ice, a form of rock, that is constantly moving under its own weight. A glacier forms where the accumulation of snow exceeds its ablation over many years, often centuries. It slowly flows and deforms under stresses induced by gravity, undergoing both ductile and brittle deformation, and acquiring distinguishing surface features, such as crevasses and seracs. As a glacier moves, it abrades underlying rock and debris to create glacial landforms, such as cirques, moraines, and fjords. Although a glacier may flow into a body of water, and can include ice shelves and ice tongues, it originates only on land and is distinct from the much thinner sea ice and lake ice that form on the surface of freezing bodies of water. On Earth, 99% of glacial ice is contained within vast ice sheets (also known as "continental glaciers") in the polar regions, but glaciers may be found in mountain ranges on every continent other than the Australian mainland, including Oceania''s high-latitude oceanic island countries such as New Zealand. Between latitudes 35°N and 35°S, glaciers occur only in the Himalayas, Andes, and a few high mountains in East Africa, Mexico, New Guinea and on Zard-Kuh in Iran. With more than 7,000 known glaciers, Pakistan has more glacial ice than any other country outside the polar regions. Glaciers cover about 10% of Earth''s land surface.
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M29-INF003', 'D', ARRAY['D']::TEXT[], 'Long-term accumulation exceeding loss implies a climate cold enough to retain snow and ice.', '{"B": "Sustained excess accumulation over years implies conditions that preserve ice.", "C": "The text says formation occurs over many years, often centuries.", "A": "Glaciers occur on every continent except the Australian mainland, including high mountains near the tropics."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M29-TS003', 'HDSAT-RW-M29-TS003', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'A glacier (US: ; UK: or ) is a persistent body of natural ice, a form of rock, that is constantly moving under its own weight. A glacier forms where the accumulation of snow exceeds its ablation over many years, often centuries. It slowly flows and deforms under stresses induced by gravity, undergoing both ductile and brittle deformation, and acquiring distinguishing surface features, such as crevasses and seracs. As a glacier moves, it abrades underlying rock and debris to create glacial landforms, such as cirques, moraines, and fjords. Although a glacier may flow into a body of water, and can include ice shelves and ice tongues, it originates only on land and is distinct from the much thinner sea ice and lake ice that form on the surface of freezing bodies of water. On Earth, 99% of glacial ice is contained within vast ice sheets (also known as "continental glaciers") in the polar regions, but glaciers may be found in mountain ranges on every continent other than the Australian mainland, including Oceania''s high-latitude oceanic island countries such as New Zealand. Between latitudes 35°N and 35°S, glaciers occur only in the Himalayas, Andes, and a few high mountains in East Africa, Mexico, New Guinea and on Zard-Kuh in Iran. With more than 7,000 known glaciers, Pakistan has more glacial ice than any other country outside the polar regions. Glaciers cover about 10% of Earth''s land surface.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It argues that glaciers cover most of Earth''s land."}, {"id": "B", "text": "It compares glaciers with icebergs in detail."}, {"id": "C", "text": "It narrates a glacier''s retreat over one summer."}, {"id": "D", "text": "It defines glaciers, explains their formation and movement, and describes their landforms and distribution."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Glacier", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Glacier', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M29-TS003', 'D', ARRAY['D']::TEXT[], 'The passage moves from definition to mechanism and then to distribution.', '{"C": "No single glacier''s retreat is narrated.", "B": "Icebergs are not discussed.", "A": "The text says glaciers cover about 10% of Earth''s land surface."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M29-CE003', 'HDSAT-RW-M29-CE003', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Textual)', 'Medium', 'multiple_choice', 'A glacier (US: ; UK: or ) is a persistent body of natural ice, a form of rock, that is constantly moving under its own weight. A glacier forms where the accumulation of snow exceeds its ablation over many years, often centuries. It slowly flows and deforms under stresses induced by gravity, undergoing both ductile and brittle deformation, and acquiring distinguishing surface features, such as crevasses and seracs. As a glacier moves, it abrades underlying rock and debris to create glacial landforms, such as cirques, moraines, and fjords. Although a glacier may flow into a body of water, and can include ice shelves and ice tongues, it originates only on land and is distinct from the much thinner sea ice and lake ice that form on the surface of freezing bodies of water. On Earth, 99% of glacial ice is contained within vast ice sheets (also known as "continental glaciers") in the polar regions, but glaciers may be found in mountain ranges on every continent other than the Australian mainland, including Oceania''s high-latitude oceanic island countries such as New Zealand. Between latitudes 35°N and 35°S, glaciers occur only in the Himalayas, Andes, and a few high mountains in East Africa, Mexico, New Guinea and on Zard-Kuh in Iran. With more than 7,000 known glaciers, Pakistan has more glacial ice than any other country outside the polar regions. Glaciers cover about 10% of Earth''s land surface.', 'Which quotation from the text most directly supports the claim that glaciers flow?', '[{"id": "A", "text": "Glaciers cover about 10% of Earth''s land surface."}, {"id": "B", "text": "A glacier is a persistent body of natural ice, a form of rock, that is constantly moving under its own weight."}, {"id": "C", "text": "It slowly flows and deforms under stresses induced by gravity, undergoing both ductile and brittle deformation, and acquiring distinguishing surface features, such as crevasses and seracs."}, {"id": "D", "text": "A glacier forms where the accumulation of snow exceeds its ablation over many years."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Glacier", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Glacier', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M29-CE003', 'C', ARRAY['C']::TEXT[], 'The correct quotation details flow, deformation, and resulting surface features.', '{"B": "This sentence defines a glacier as moving.", "D": "This sentence describes formation conditions.", "A": "This sentence describes land coverage."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M29-CI004', 'HDSAT-RW-M29-CI004', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'The water cycle (or hydrologic cycle or hydrological cycle) is a biogeochemical cycle that involves the continuous change in form of water on, above and below the surface of the Earth across different reservoirs. The mass of water on Earth remains fairly constant over time. However, the partitioning of the water into the major reservoirs of ice, fresh water, salt water and atmospheric water is variable and depends on climatic variables. The water moves from one reservoir to another, such as from river to ocean, or from the ocean to the atmosphere due to a variety of physical and chemical processes. The processes that drive these movements, or fluxes, are evaporation, transpiration, condensation, precipitation, sublimation, infiltration, surface runoff, and subsurface flow. In doing so, the water goes through different phases: liquid, solid (ice) and vapor. The ocean plays a key role in the water cycle as it is the source of 86% of global evaporation. The water cycle is driven by energy exchanges in the form of heat transfers between different phases. The energy released or absorbed during a phase change can result in temperature changes. Heat is absorbed as water transitions from the liquid to the vapor phase through evaporation. This heat is also known as the latent heat of vaporization. Conversely, when water condenses or melts from solid ice it releases energy and heat.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Water on Earth exists only in liquid form."}, {"id": "B", "text": "The water cycle is driven by gravity alone."}, {"id": "C", "text": "The water cycle continuously moves a fixed mass of water among reservoirs through processes driven by heat exchange."}, {"id": "D", "text": "The water cycle creates new water each year."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Water cycle", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Water_cycle', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M29-CI004', 'C', ARRAY['C']::TEXT[], 'The passage defines the water cycle, lists its processes, and explains the role of heat and the ocean.', '{"D": "The text says the mass of water on Earth remains fairly constant.", "A": "The text says water goes through liquid, solid, and vapor phases.", "B": "The text says the cycle is driven by energy exchanges in the form of heat transfers."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M29-INF004', 'HDSAT-RW-M29-INF004', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'The water cycle (or hydrologic cycle or hydrological cycle) is a biogeochemical cycle that involves the continuous change in form of water on, above and below the surface of the Earth across different reservoirs. The mass of water on Earth remains fairly constant over time. However, the partitioning of the water into the major reservoirs of ice, fresh water, salt water and atmospheric water is variable and depends on climatic variables. The water moves from one reservoir to another, such as from river to ocean, or from the ocean to the atmosphere due to a variety of physical and chemical processes. The processes that drive these movements, or fluxes, are evaporation, transpiration, condensation, precipitation, sublimation, infiltration, surface runoff, and subsurface flow. In doing so, the water goes through different phases: liquid, solid (ice) and vapor. The ocean plays a key role in the water cycle as it is the source of 86% of global evaporation. The water cycle is driven by energy exchanges in the form of heat transfers between different phases. The energy released or absorbed during a phase change can result in temperature changes. Heat is absorbed as water transitions from the liquid to the vapor phase through evaporation. This heat is also known as the latent heat of vaporization. Conversely, when water condenses or melts from solid ice it releases energy and heat.
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M29-INF004', 'A', ARRAY['A']::TEXT[], 'Absorbing heat in one place and releasing it in another transfers energy through the cycle.', '{"B": "The text says heat is absorbed during evaporation and released during condensation.", "D": "Energy is transferred, not destroyed.", "C": "The text says the cycle is driven by heat transfers."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M29-TS004', 'HDSAT-RW-M29-TS004', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'The water cycle (or hydrologic cycle or hydrological cycle) is a biogeochemical cycle that involves the continuous change in form of water on, above and below the surface of the Earth across different reservoirs. The mass of water on Earth remains fairly constant over time. However, the partitioning of the water into the major reservoirs of ice, fresh water, salt water and atmospheric water is variable and depends on climatic variables. The water moves from one reservoir to another, such as from river to ocean, or from the ocean to the atmosphere due to a variety of physical and chemical processes. The processes that drive these movements, or fluxes, are evaporation, transpiration, condensation, precipitation, sublimation, infiltration, surface runoff, and subsurface flow. In doing so, the water goes through different phases: liquid, solid (ice) and vapor. The ocean plays a key role in the water cycle as it is the source of 86% of global evaporation. The water cycle is driven by energy exchanges in the form of heat transfers between different phases. The energy released or absorbed during a phase change can result in temperature changes. Heat is absorbed as water transitions from the liquid to the vapor phase through evaporation. This heat is also known as the latent heat of vaporization. Conversely, when water condenses or melts from solid ice it releases energy and heat.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It defines the cycle and its reservoirs, lists the processes that move water, and explains the heat exchanges involved."}, {"id": "B", "text": "It compares the water cycle with the carbon cycle."}, {"id": "C", "text": "It narrates a single rainstorm."}, {"id": "D", "text": "It argues that water is destroyed over time."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Water cycle", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Water_cycle', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M29-TS004', 'A', ARRAY['A']::TEXT[], 'The passage moves from definition and reservoirs to processes and energy.', '{"C": "No individual storm is described.", "B": "The carbon cycle is not mentioned.", "D": "The text says the mass of water remains fairly constant."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M29-CE004', 'HDSAT-RW-M29-CE004', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Textual)', 'Medium', 'multiple_choice', 'The water cycle (or hydrologic cycle or hydrological cycle) is a biogeochemical cycle that involves the continuous change in form of water on, above and below the surface of the Earth across different reservoirs. The mass of water on Earth remains fairly constant over time. However, the partitioning of the water into the major reservoirs of ice, fresh water, salt water and atmospheric water is variable and depends on climatic variables. The water moves from one reservoir to another, such as from river to ocean, or from the ocean to the atmosphere due to a variety of physical and chemical processes. The processes that drive these movements, or fluxes, are evaporation, transpiration, condensation, precipitation, sublimation, infiltration, surface runoff, and subsurface flow. In doing so, the water goes through different phases: liquid, solid (ice) and vapor. The ocean plays a key role in the water cycle as it is the source of 86% of global evaporation. The water cycle is driven by energy exchanges in the form of heat transfers between different phases. The energy released or absorbed during a phase change can result in temperature changes. Heat is absorbed as water transitions from the liquid to the vapor phase through evaporation. This heat is also known as the latent heat of vaporization. Conversely, when water condenses or melts from solid ice it releases energy and heat.', 'Which quotation from the text most directly supports the claim that the ocean drives most evaporation?', '[{"id": "A", "text": "The water cycle is a biogeochemical cycle that involves the continuous change in form of water on, above and below the surface of the Earth."}, {"id": "B", "text": "The ocean plays a key role in the water cycle as it is the source of 86% of global evaporation."}, {"id": "C", "text": "The processes that drive these movements include evaporation, transpiration, condensation, precipitation, and infiltration."}, {"id": "D", "text": "The mass of water on Earth remains fairly constant over time."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Water cycle", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Water_cycle', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M29-CE004', 'B', ARRAY['B']::TEXT[], 'The correct quotation gives the ocean''s 86% share of global evaporation.', '{"A": "This sentence defines the water cycle.", "D": "This sentence describes the constancy of water mass.", "C": "This sentence lists the cycle''s processes."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M29-CI005', 'HDSAT-RW-M29-CI005', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'El Niño–Southern Oscillation (ENSO) is a global climate phenomenon that emerges from variation in winds and sea surface temperatures over the tropical Pacific Ocean. Those variations have an irregular pattern, but do have some appearance of cycles. The occurrence of ENSO is not easily predictable. It affects the climate of much of the tropics and subtropics, and has links (teleconnections) to higher-latitude regions of the world. The warming phase of the sea surface temperature is known as "El Niño" and the cooling phase as "La Niña". The Southern Oscillation is the accompanying atmospheric oscillation, which is coupled with the sea temperature change. El Niño is associated with higher than normal sea level air pressure over Indonesia and Australia, and across the Indian Ocean to the Atlantic Ocean. La Niña has roughly the reverse pattern: high pressure over the central and eastern Pacific and lower pressure through much of the rest of the tropics and subtropics. The two phenomena typically last approximately one year each and typically occur every two to seven years with varying intensity, with neutral periods of lower intensity interspersed. El Niño events can be more intense, but La Niña events may repeat and last longer. A key mechanism of ENSO is the Bjerknes feedback (named after Jacob Bjerknes in 1969) in which the atmospheric changes alter the sea temperatures that, in turn, alter the atmospheric winds in a positive feedback.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "ENSO is an irregular Pacific climate pattern of alternating warm and cool phases that affects weather far beyond the tropics."}, {"id": "B", "text": "El Niño is the cooling phase of the Pacific."}, {"id": "C", "text": "ENSO is a predictable annual cycle with identical phases."}, {"id": "D", "text": "ENSO affects only the tropical Pacific and no other region."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "El Niño–Southern Oscillation", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/El_Ni%C3%B1o%E2%80%93Southern_Oscillation', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M29-CI005', 'A', ARRAY['A']::TEXT[], 'The passage defines ENSO, describes its phases and timing, and explains its global links.', '{"C": "The text says the pattern is irregular and not easily predictable.", "B": "The text says El Niño is the warming phase and La Niña the cooling phase.", "D": "The text says ENSO has teleconnections to higher-latitude regions."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M29-INF005', 'HDSAT-RW-M29-INF005', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'El Niño–Southern Oscillation (ENSO) is a global climate phenomenon that emerges from variation in winds and sea surface temperatures over the tropical Pacific Ocean. Those variations have an irregular pattern, but do have some appearance of cycles. The occurrence of ENSO is not easily predictable. It affects the climate of much of the tropics and subtropics, and has links (teleconnections) to higher-latitude regions of the world. The warming phase of the sea surface temperature is known as "El Niño" and the cooling phase as "La Niña". The Southern Oscillation is the accompanying atmospheric oscillation, which is coupled with the sea temperature change. El Niño is associated with higher than normal sea level air pressure over Indonesia and Australia, and across the Indian Ocean to the Atlantic Ocean. La Niña has roughly the reverse pattern: high pressure over the central and eastern Pacific and lower pressure through much of the rest of the tropics and subtropics. The two phenomena typically last approximately one year each and typically occur every two to seven years with varying intensity, with neutral periods of lower intensity interspersed. El Niño events can be more intense, but La Niña events may repeat and last longer. A key mechanism of ENSO is the Bjerknes feedback (named after Jacob Bjerknes in 1969) in which the atmospheric changes alter the sea temperatures that, in turn, alter the atmospheric winds in a positive feedback.
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M29-INF005', 'D', ARRAY['D']::TEXT[], 'If ENSO''s timing is hard to predict, forecasts that depend on it inherit that uncertainty.', '{"A": "An unpredictable onset limits forecast confidence.", "C": "The text says the pattern is irregular and not easily predictable.", "B": "The phenomenon is defined by Pacific winds and sea temperatures."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M29-TS005', 'HDSAT-RW-M29-TS005', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'El Niño–Southern Oscillation (ENSO) is a global climate phenomenon that emerges from variation in winds and sea surface temperatures over the tropical Pacific Ocean. Those variations have an irregular pattern, but do have some appearance of cycles. The occurrence of ENSO is not easily predictable. It affects the climate of much of the tropics and subtropics, and has links (teleconnections) to higher-latitude regions of the world. The warming phase of the sea surface temperature is known as "El Niño" and the cooling phase as "La Niña". The Southern Oscillation is the accompanying atmospheric oscillation, which is coupled with the sea temperature change. El Niño is associated with higher than normal sea level air pressure over Indonesia and Australia, and across the Indian Ocean to the Atlantic Ocean. La Niña has roughly the reverse pattern: high pressure over the central and eastern Pacific and lower pressure through much of the rest of the tropics and subtropics. The two phenomena typically last approximately one year each and typically occur every two to seven years with varying intensity, with neutral periods of lower intensity interspersed. El Niño events can be more intense, but La Niña events may repeat and last longer. A key mechanism of ENSO is the Bjerknes feedback (named after Jacob Bjerknes in 1969) in which the atmospheric changes alter the sea temperatures that, in turn, alter the atmospheric winds in a positive feedback.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It argues that ENSO can be predicted perfectly."}, {"id": "B", "text": "It defines ENSO, contrasts its warm and cool phases, describes their timing, and explains a key feedback."}, {"id": "C", "text": "It compares ENSO with the water cycle."}, {"id": "D", "text": "It narrates a single El Niño event."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "El Niño–Southern Oscillation", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/El_Ni%C3%B1o%E2%80%93Southern_Oscillation', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M29-TS005', 'B', ARRAY['B']::TEXT[], 'The passage moves from definition to phases, timing, and mechanism.', '{"D": "No single event is narrated.", "C": "The water cycle is not mentioned.", "A": "The text says ENSO''s occurrence is not easily predictable."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M29-CE005', 'HDSAT-RW-M29-CE005', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Textual)', 'Medium', 'multiple_choice', 'El Niño–Southern Oscillation (ENSO) is a global climate phenomenon that emerges from variation in winds and sea surface temperatures over the tropical Pacific Ocean. Those variations have an irregular pattern, but do have some appearance of cycles. The occurrence of ENSO is not easily predictable. It affects the climate of much of the tropics and subtropics, and has links (teleconnections) to higher-latitude regions of the world. The warming phase of the sea surface temperature is known as "El Niño" and the cooling phase as "La Niña". The Southern Oscillation is the accompanying atmospheric oscillation, which is coupled with the sea temperature change. El Niño is associated with higher than normal sea level air pressure over Indonesia and Australia, and across the Indian Ocean to the Atlantic Ocean. La Niña has roughly the reverse pattern: high pressure over the central and eastern Pacific and lower pressure through much of the rest of the tropics and subtropics. The two phenomena typically last approximately one year each and typically occur every two to seven years with varying intensity, with neutral periods of lower intensity interspersed. El Niño events can be more intense, but La Niña events may repeat and last longer. A key mechanism of ENSO is the Bjerknes feedback (named after Jacob Bjerknes in 1969) in which the atmospheric changes alter the sea temperatures that, in turn, alter the atmospheric winds in a positive feedback.', 'Which quotation from the text most directly supports the claim that ENSO affects regions far from the tropics?', '[{"id": "A", "text": "The two phenomena typically last approximately one year each and typically occur every two to seven years."}, {"id": "B", "text": "It affects the climate of much of the tropics and subtropics, and has links (teleconnections) to higher-latitude regions of the world."}, {"id": "C", "text": "The warming phase of the sea surface temperature is known as El Niño and the cooling phase as La Niña."}, {"id": "D", "text": "El Niño–Southern Oscillation is a global climate phenomenon that emerges from variation in winds and sea surface temperatures over the tropical Pacific Ocean."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "El Niño–Southern Oscillation", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/El_Ni%C3%B1o%E2%80%93Southern_Oscillation', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M29-CE005', 'B', ARRAY['B']::TEXT[], 'The correct quotation explicitly mentions teleconnections to higher latitudes.', '{"D": "This sentence defines ENSO.", "C": "This sentence names the phases.", "A": "This sentence describes timing."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M29-CI006', 'HDSAT-RW-M29-CI006', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'Desertification is a type of gradual land degradation of fertile land into arid desert due to a combination of natural processes and human activities. The immediate cause of desertification is the loss of most vegetation. This is driven by a number of factors, alone or in combination, such as drought, climatic shifts, acid rain, tillage for agriculture, overgrazing and deforestation for fuel or construction of materials. Though vegetation plays a major role in determining the biological composition of the soil, studies have shown that, in many environments, the rate of erosion and runoff decreases exponentially with increased vegetation cover. Unprotected, dry soil surfaces blow away with the wind or are washed away by flash floods, leaving infertile lower soil layers that bake in the sun and become an unproductive hardpan. At least 90% of the inhabitants of drylands live in developing countries, where they also suffer from poor economic and social conditions. This situation is exacerbated by land degradation because of the reduction in productivity, the precariousness of living conditions and the difficulty of access to resources and opportunities. Geographic areas most affected are located in Africa (Sahel region), Asia (Gobi Desert and Mongolia) and parts of South America. Drylands occupy approximately 40–41% of Earth''s land area and are home to more than 2 billion people. Effects of desertification include sand and dust storms, food insecurity, and poverty.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Desertification affects only wealthy countries."}, {"id": "B", "text": "Desertification is the natural expansion of forests."}, {"id": "C", "text": "Desertification is caused only by volcanic eruptions."}, {"id": "D", "text": "Desertification is the degradation of fertile land into desert, driven by natural and human factors and harming dryland populations."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Desertification", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Desertification', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M29-CI006', 'D', ARRAY['D']::TEXT[], 'The passage defines desertification, explains its causes, and describes its human and environmental effects.', '{"B": "The text defines it as gradual land degradation into arid desert.", "C": "The text lists drought, tillage, overgrazing, and deforestation.", "A": "The text says at least 90% of dryland inhabitants live in developing countries."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M29-INF006', 'HDSAT-RW-M29-INF006', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'Desertification is a type of gradual land degradation of fertile land into arid desert due to a combination of natural processes and human activities. The immediate cause of desertification is the loss of most vegetation. This is driven by a number of factors, alone or in combination, such as drought, climatic shifts, acid rain, tillage for agriculture, overgrazing and deforestation for fuel or construction of materials. Though vegetation plays a major role in determining the biological composition of the soil, studies have shown that, in many environments, the rate of erosion and runoff decreases exponentially with increased vegetation cover. Unprotected, dry soil surfaces blow away with the wind or are washed away by flash floods, leaving infertile lower soil layers that bake in the sun and become an unproductive hardpan. At least 90% of the inhabitants of drylands live in developing countries, where they also suffer from poor economic and social conditions. This situation is exacerbated by land degradation because of the reduction in productivity, the precariousness of living conditions and the difficulty of access to resources and opportunities. Geographic areas most affected are located in Africa (Sahel region), Asia (Gobi Desert and Mongolia) and parts of South America. Drylands occupy approximately 40–41% of Earth''s land area and are home to more than 2 billion people. Effects of desertification include sand and dust storms, food insecurity, and poverty.
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M29-INF006', 'B', ARRAY['B']::TEXT[], 'If vegetation reduces erosion exponentially, its removal would sharply increase erosion and degradation.', '{"A": "Less vegetation means more erosion and runoff, which degrade land.", "D": "Vegetation cover reduces erosion; removing it does the opposite.", "C": "The text says vegetation loss is the immediate cause of desertification."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M29-TS006', 'HDSAT-RW-M29-TS006', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'Desertification is a type of gradual land degradation of fertile land into arid desert due to a combination of natural processes and human activities. The immediate cause of desertification is the loss of most vegetation. This is driven by a number of factors, alone or in combination, such as drought, climatic shifts, acid rain, tillage for agriculture, overgrazing and deforestation for fuel or construction of materials. Though vegetation plays a major role in determining the biological composition of the soil, studies have shown that, in many environments, the rate of erosion and runoff decreases exponentially with increased vegetation cover. Unprotected, dry soil surfaces blow away with the wind or are washed away by flash floods, leaving infertile lower soil layers that bake in the sun and become an unproductive hardpan. At least 90% of the inhabitants of drylands live in developing countries, where they also suffer from poor economic and social conditions. This situation is exacerbated by land degradation because of the reduction in productivity, the precariousness of living conditions and the difficulty of access to resources and opportunities. Geographic areas most affected are located in Africa (Sahel region), Asia (Gobi Desert and Mongolia) and parts of South America. Drylands occupy approximately 40–41% of Earth''s land area and are home to more than 2 billion people. Effects of desertification include sand and dust storms, food insecurity, and poverty.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It profiles a single dryland farmer."}, {"id": "B", "text": "It argues that desertification is irreversible."}, {"id": "C", "text": "It compares desertification with deforestation in a table."}, {"id": "D", "text": "It defines desertification, explains its causes, identifies affected regions, and lists its effects."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Desertification", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Desertification', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M29-TS006', 'D', ARRAY['D']::TEXT[], 'The passage moves from definition to causes, geography, and consequences.', '{"A": "No individual is profiled.", "C": "No table appears.", "B": "The text describes degradation without declaring it irreversible."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M29-CE006', 'HDSAT-RW-M29-CE006', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Textual)', 'Medium', 'multiple_choice', 'Desertification is a type of gradual land degradation of fertile land into arid desert due to a combination of natural processes and human activities. The immediate cause of desertification is the loss of most vegetation. This is driven by a number of factors, alone or in combination, such as drought, climatic shifts, acid rain, tillage for agriculture, overgrazing and deforestation for fuel or construction of materials. Though vegetation plays a major role in determining the biological composition of the soil, studies have shown that, in many environments, the rate of erosion and runoff decreases exponentially with increased vegetation cover. Unprotected, dry soil surfaces blow away with the wind or are washed away by flash floods, leaving infertile lower soil layers that bake in the sun and become an unproductive hardpan. At least 90% of the inhabitants of drylands live in developing countries, where they also suffer from poor economic and social conditions. This situation is exacerbated by land degradation because of the reduction in productivity, the precariousness of living conditions and the difficulty of access to resources and opportunities. Geographic areas most affected are located in Africa (Sahel region), Asia (Gobi Desert and Mongolia) and parts of South America. Drylands occupy approximately 40–41% of Earth''s land area and are home to more than 2 billion people. Effects of desertification include sand and dust storms, food insecurity, and poverty.', 'Which quotation from the text most directly supports the claim that human land use contributes to desertification?', '[{"id": "A", "text": "Desertification is a type of gradual land degradation of fertile land into arid desert."}, {"id": "B", "text": "The immediate cause of desertification is the loss of most vegetation."}, {"id": "C", "text": "This is driven by a number of factors, alone or in combination, such as drought, climatic shifts, acid rain, tillage for agriculture, overgrazing and deforestation for fuel or construction of materials."}, {"id": "D", "text": "Drylands occupy approximately 40–41% of Earth''s land area and are home to more than 2 billion people."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Desertification", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Desertification', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M29-CE006', 'C', ARRAY['C']::TEXT[], 'The correct quotation lists tillage, overgrazing, and deforestation as drivers.', '{"A": "This sentence defines desertification.", "B": "This sentence identifies the immediate cause.", "D": "This sentence describes dryland extent and population."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M29-CI007', 'HDSAT-RW-M29-CI007', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'A peatland is a type of wetland whose soils consist of organic matter from decaying plants, forming layers of peat. Peatlands arise because of incomplete decomposition of organic matter, usually litter from vegetation, due to water-logging and subsequent anoxia. Peatlands are unusual landforms that derive mostly from biological rather than physical processes, and can take on characteristic shapes and surface patterning. The formation of peatlands is primarily controlled by climatic conditions such as precipitation and temperature, although terrain relief is a major factor as waterlogging occurs more easily on flatter ground and in basins. Peat formation typically initiates as a paludification of a mineral soil forest, terrestrialisation of lakes, or primary peat formation on bare soils on previously glaciated areas. A peatland that is actively forming peat is called a mire. All types of mires share the common characteristic of being saturated with water, at least seasonally with actively forming peat, while having their own ecosystem. Peatlands are the largest natural carbon store on land. Covering around 3 million km2 globally, they sequester 0.37 gigatons (Gt) of carbon dioxide (CO2) a year. Peat soils store over 600 Gt of carbon, more than the carbon stored in all other vegetation types, including forests. In their natural state, peatlands provide a range of ecosystem services, including minimising flood risk and erosion, purifying water and regulating climate.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Peatlands store less carbon than forests."}, {"id": "B", "text": "Peatlands are waterlogged wetlands of partly decomposed plants that store more carbon than any other land ecosystem."}, {"id": "C", "text": "Peatlands are dry grasslands with little organic matter."}, {"id": "D", "text": "Peatlands form only from volcanic activity."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Peatland", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Peatland', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M29-CI007', 'B', ARRAY['B']::TEXT[], 'The passage defines peatlands, explains their formation, and describes their carbon storage and services.', '{"C": "The text describes soils of decaying plants forming peat layers.", "A": "The text says peat soils store more carbon than all other vegetation types, including forests.", "D": "The text says peatlands derive mostly from biological rather than physical processes."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M29-INF007', 'HDSAT-RW-M29-INF007', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'A peatland is a type of wetland whose soils consist of organic matter from decaying plants, forming layers of peat. Peatlands arise because of incomplete decomposition of organic matter, usually litter from vegetation, due to water-logging and subsequent anoxia. Peatlands are unusual landforms that derive mostly from biological rather than physical processes, and can take on characteristic shapes and surface patterning. The formation of peatlands is primarily controlled by climatic conditions such as precipitation and temperature, although terrain relief is a major factor as waterlogging occurs more easily on flatter ground and in basins. Peat formation typically initiates as a paludification of a mineral soil forest, terrestrialisation of lakes, or primary peat formation on bare soils on previously glaciated areas. A peatland that is actively forming peat is called a mire. All types of mires share the common characteristic of being saturated with water, at least seasonally with actively forming peat, while having their own ecosystem. Peatlands are the largest natural carbon store on land. Covering around 3 million km2 globally, they sequester 0.37 gigatons (Gt) of carbon dioxide (CO2) a year. Peat soils store over 600 Gt of carbon, more than the carbon stored in all other vegetation types, including forests. In their natural state, peatlands provide a range of ecosystem services, including minimising flood risk and erosion, purifying water and regulating climate.
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M29-INF007', 'B', ARRAY['B']::TEXT[], 'Without oxygen, decomposition stalls and plant matter builds up as peat.', '{"A": "The text says peatlands arise from incomplete decomposition due to water-logging and anoxia.", "C": "Anoxic conditions slow decomposition.", "D": "Peat is partly decomposed plant matter, not fully consumed."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M29-TS007', 'HDSAT-RW-M29-TS007', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'A peatland is a type of wetland whose soils consist of organic matter from decaying plants, forming layers of peat. Peatlands arise because of incomplete decomposition of organic matter, usually litter from vegetation, due to water-logging and subsequent anoxia. Peatlands are unusual landforms that derive mostly from biological rather than physical processes, and can take on characteristic shapes and surface patterning. The formation of peatlands is primarily controlled by climatic conditions such as precipitation and temperature, although terrain relief is a major factor as waterlogging occurs more easily on flatter ground and in basins. Peat formation typically initiates as a paludification of a mineral soil forest, terrestrialisation of lakes, or primary peat formation on bare soils on previously glaciated areas. A peatland that is actively forming peat is called a mire. All types of mires share the common characteristic of being saturated with water, at least seasonally with actively forming peat, while having their own ecosystem. Peatlands are the largest natural carbon store on land. Covering around 3 million km2 globally, they sequester 0.37 gigatons (Gt) of carbon dioxide (CO2) a year. Peat soils store over 600 Gt of carbon, more than the carbon stored in all other vegetation types, including forests. In their natural state, peatlands provide a range of ecosystem services, including minimising flood risk and erosion, purifying water and regulating climate.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It argues that peatlands should be drained."}, {"id": "B", "text": "It narrates the harvest of peat for fuel."}, {"id": "C", "text": "It defines peatlands, explains their formation and controls, and describes their carbon storage and ecosystem services."}, {"id": "D", "text": "It compares peatlands with tropical rainforests in detail."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Peatland", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Peatland', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
