INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M29-CE008', 'HDSAT-RW-M29-CE008', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Textual)', 'Medium', 'multiple_choice', 'Ozone depletion in the stratosphere (the ozone layer) consists of two related phenomena observed since the late 1970s: a lowered total amount of ozone in Earth''s upper stratosphere, and a much larger springtime decrease in around Earth''s polar regions. The latter phenomenon over the south pole is referred to as the ozone hole. There are also springtime polar tropospheric ozone depletion events in addition to these stratospheric events. The main causes of ozone depletion and the ozone hole are manufactured chemicals, especially manufactured halocarbon refrigerants, solvents, propellants, and foam-blowing agents (chlorofluorocarbons (CFCs), HCFCs, halons), referred to as ozone-depleting substances (ODS). These compounds are transported into the stratosphere by turbulent mixing after being emitted from the surface, mixing much faster than the molecules can settle. Once in the stratosphere, they release atoms from the halogen group through photodissociation, which catalyze the breakdown of ozone (O3) into oxygen (O2). Ozone depletion in both the upper and lower stratosphere were observed to increase as emissions of halocarbons increased. Ozone depletion and the ozone hole have generated worldwide concern over increased cancer risks and other negative effects. The ozone layer prevents harmful wavelengths of ultraviolet (UVB) light from passing through the Earth''s atmosphere.', 'Which quotation from the text most directly supports the claim that manufactured chemicals cause ozone depletion?', '[{"id": "A", "text": "The ozone layer prevents harmful wavelengths of ultraviolet (UVB) light from passing through the Earth''s atmosphere."}, {"id": "B", "text": "Ozone depletion in the stratosphere consists of two related phenomena observed since the late 1970s."}, {"id": "C", "text": "The main causes of ozone depletion and the ozone hole are manufactured chemicals, especially manufactured halocarbon refrigerants, solvents, propellants, and foam-blowing agents (chlorofluorocarbons (CFCs), HCFCs, halons), referred to as ozone-depleting substances (ODS)."}, {"id": "D", "text": "Ozone depletion and the ozone hole have generated worldwide concern over increased cancer risks."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Ozone depletion", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Ozone_depletion', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M29-CE008', 'C', ARRAY['C']::TEXT[], 'The correct quotation names halocarbon refrigerants, solvents, propellants, and foam-blowing agents as the main causes.', '{"B": "This sentence dates the phenomena.", "A": "This sentence describes the ozone layer''s protective role.", "D": "This sentence describes public concern."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M29-CI009', 'HDSAT-RW-M29-CI009', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'A monsoon () is traditionally a seasonal reversing wind accompanied by corresponding changes in precipitation, but now used to describe seasonal changes in atmospheric circulation and precipitation associated with annual latitudinal oscillation of the Intertropical Convergence Zone, specifically between its limits to the north and south of the equator. Usually, the term monsoon is used to refer to the rainy phase of a seasonally changing pattern, although technically there is a dry phase. The term is also used to describe locally heavy but short-term rains. The major monsoon systems of the world consist of the West African, South Asian–Australian, North American, and South American monsoons. The term was first used in English in British India and neighbouring countries, referring to big seasonal winds blowing from the Bay of Bengal and Arabian Sea in the southwest that brought heavy rainfall to the area. == Etymology == The etymology of the word monsoon is not wholly certain. The English monsoon came from Portuguese monção, ultimately from Arabic موسم (mawsim, "season"), "but partly via early modern Dutch monson". == History == === Asian monsoon === Strengthening of the Asian monsoon has been linked to the uplift of the Tibetan Plateau after the collision of the Indian subcontinent and Asia around 50 million years ago.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "A monsoon is a seasonal reversal of winds and precipitation, with major systems in Africa, Asia, and the Americas."}, {"id": "B", "text": "Monsoons occur only in South America."}, {"id": "C", "text": "A monsoon is a single violent thunderstorm."}, {"id": "D", "text": "A monsoon has no dry phase."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Monsoon", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Monsoon', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
