INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M29-CE009', 'HDSAT-RW-M29-CE009', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Textual)', 'Medium', 'multiple_choice', 'A monsoon () is traditionally a seasonal reversing wind accompanied by corresponding changes in precipitation, but now used to describe seasonal changes in atmospheric circulation and precipitation associated with annual latitudinal oscillation of the Intertropical Convergence Zone, specifically between its limits to the north and south of the equator. Usually, the term monsoon is used to refer to the rainy phase of a seasonally changing pattern, although technically there is a dry phase. The term is also used to describe locally heavy but short-term rains. The major monsoon systems of the world consist of the West African, South Asian–Australian, North American, and South American monsoons. The term was first used in English in British India and neighbouring countries, referring to big seasonal winds blowing from the Bay of Bengal and Arabian Sea in the southwest that brought heavy rainfall to the area. == Etymology == The etymology of the word monsoon is not wholly certain. The English monsoon came from Portuguese monção, ultimately from Arabic موسم (mawsim, "season"), "but partly via early modern Dutch monson". == History == === Asian monsoon === Strengthening of the Asian monsoon has been linked to the uplift of the Tibetan Plateau after the collision of the Indian subcontinent and Asia around 50 million years ago.', 'Which quotation from the text most directly supports the claim that a monsoon involves seasonal wind reversal?', '[{"id": "A", "text": "A monsoon is traditionally a seasonal reversing wind accompanied by corresponding changes in precipitation, but now used to describe seasonal changes in atmospheric circulation and precipitation associated with annual latitudinal oscillation of the Intertropical Convergence Zone."}, {"id": "B", "text": "Usually, the term monsoon is used to refer to the rainy phase of a seasonally changing pattern."}, {"id": "C", "text": "The major monsoon systems of the world consist of the West African, South Asian–Australian, North American, and South American monsoons."}, {"id": "D", "text": "The English monsoon came from Portuguese monção, ultimately from Arabic موسم (mawsim, season)."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Monsoon", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Monsoon', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
