INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M29-CI010', 'HDSAT-RW-M29-CI010', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'An earthquake, also called a quake, tremor, or temblor, is the shaking of the Earth''s surface resulting from a sudden release of energy in the lithosphere that creates seismic waves. Earthquakes can range in intensity, from those so weak they cannot be felt, to those violent enough to propel objects and people into the air, damage critical infrastructure, and wreak destruction across entire cities. The seismic activity of an area is the frequency, type, and size of earthquakes experienced over a particular time. The seismicity at a particular location in the Earth is the average rate of seismic energy released per unit volume. In its most general sense, the word earthquake is used to describe any seismic event that generates seismic waves. Earthquakes can occur naturally or be induced by human activities, such as mining, fracking, and nuclear weapons testing. The initial point of rupture is called the hypocenter or focus, while the ground level directly above it is the epicenter. Earthquakes are primarily caused by geological faults, but also by volcanism, landslides, and other seismic events. Significant historical earthquakes include the 1976 Tangshan earthquake in China, with over 300,000 fatalities, and the 1960 Valdivia earthquake in Chile, the largest ever recorded at 9.5 magnitude. Earthquakes in some cases may result in various effects, such as ground shaking and soil liquefaction, sometimes leading to significant damage and loss of life.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "An earthquake is ground shaking from sudden energy release in the lithosphere, caused mainly by faults and sometimes by human activity."}, {"id": "B", "text": "Earthquakes cannot be caused by human activity."}, {"id": "C", "text": "Earthquakes are caused only by volcanic eruptions."}, {"id": "D", "text": "The epicenter is the point of rupture underground."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Earthquake", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Earthquake', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M29-CI010', 'A', ARRAY['A']::TEXT[], 'The passage defines earthquakes, explains causes and terminology, and gives historical examples.', '{"C": "The text says earthquakes are primarily caused by geological faults, but also by volcanism and landslides.", "B": "The text says mining, fracking, and nuclear testing can induce earthquakes.", "D": "The text says the hypocenter is the rupture point; the epicenter is directly above it."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M29-INF010', 'HDSAT-RW-M29-INF010', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'An earthquake, also called a quake, tremor, or temblor, is the shaking of the Earth''s surface resulting from a sudden release of energy in the lithosphere that creates seismic waves. Earthquakes can range in intensity, from those so weak they cannot be felt, to those violent enough to propel objects and people into the air, damage critical infrastructure, and wreak destruction across entire cities. The seismic activity of an area is the frequency, type, and size of earthquakes experienced over a particular time. The seismicity at a particular location in the Earth is the average rate of seismic energy released per unit volume. In its most general sense, the word earthquake is used to describe any seismic event that generates seismic waves. Earthquakes can occur naturally or be induced by human activities, such as mining, fracking, and nuclear weapons testing. The initial point of rupture is called the hypocenter or focus, while the ground level directly above it is the epicenter. Earthquakes are primarily caused by geological faults, but also by volcanism, landslides, and other seismic events. Significant historical earthquakes include the 1976 Tangshan earthquake in China, with over 300,000 fatalities, and the 1960 Valdivia earthquake in Chile, the largest ever recorded at 9.5 magnitude. Earthquakes in some cases may result in various effects, such as ground shaking and soil liquefaction, sometimes leading to significant damage and loss of life.
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M29-INF010', 'D', ARRAY['D']::TEXT[], 'The epicenter is by definition the surface point above the rupture.', '{"A": "The text defines the epicenter as the ground level directly above the focus.", "B": "The epicenter is at the surface, not in the mantle.", "C": "The definition ties it directly to the hypocenter."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
