an be human-induced?', '[{"id": "A", "text": "The initial point of rupture is called the hypocenter or focus."}, {"id": "B", "text": "Earthquakes can occur naturally or be induced by human activities, such as mining, fracking, and nuclear weapons testing."}, {"id": "C", "text": "An earthquake is the shaking of the Earth''s surface resulting from a sudden release of energy in the lithosphere."}, {"id": "D", "text": "The 1960 Valdivia earthquake in Chile was the largest ever recorded at 9.5 magnitude."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Earthquake", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Earthquake', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
